import json

questions = []

def add_q(qid, category, question, options, correct_idx, explanation):
    assert len(options) == 5, f"{qid} must have 5 options"
    assert 0 <= correct_idx < 5, f"{qid} index invalid"
    opts = []
    for i, opt in enumerate(options):
        opts.append({"text": opt, "is_correct": (i == correct_idx)})
    questions.append({
        "id": qid,
        "category": category,
        "question": question,
        "options": opts,
        "explanation": explanation
    })

CAT7 = "Somatosensory DCML Pathway & Mechanoreceptors"
CAT8 = "Anterolateral System & Spinal Cord Syndromes"
CAT9 = "Trigeminal System, Facial Sensation & Reflexes"

